// org.client.list — E1 AC1. Generated by `pnpm gen:query`; guard cases kept, acceptance case added.
// Row isolation for client users is proven in packages/db (client.rls.int.test.ts).
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createTestDatabase, type TestDatabase } from '@ocs/testing';
import { Forbidden, openTestKernel, type TestKernel } from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';
import { clientList } from '../queries/client-list.ts';

const pm = aStaffActor({ roles: ['pm'] });
const other = aStaffActor();
let testDb: TestDatabase;
let t: TestKernel;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(pm, clientList.permission, createClient.permission);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.client.list', () => {
  it('refuses an actor without the permission', async () => {
    await expect(t.kernel.read(clientList, other, {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('lists the clients by short code', async () => {
    for (const [shortCode, name] of [
      ['CLIENTC', 'Client C'],
      ['CLIENTA', 'Client A'],
    ] as const) {
      await t.kernel.execute(createClient, pm, { shortCode, name }, 'test');
    }
    const list = await t.kernel.read(clientList, pm, {});
    expect(list.map((c) => [c.shortCode, c.name])).toEqual([
      ['CLIENTA', 'Client A'],
      ['CLIENTC', 'Client C'],
    ]);
  });
});
